// Requiere: npm i web-push en el entorno de n8n
// y variable de entorno  NODE_FUNCTION_ALLOW_EXTERNAL=web-push
const webpush = require('web-push');

// ⬇️ REEMPLAZA con TUS claves (genera con: npx web-push generate-vapid-keys)
const VAPID_PUBLIC  = 'PEGA_TU_CLAVE_PUBLICA';
const VAPID_PRIVATE = 'PEGA_TU_CLAVE_PRIVADA';
const CONTACT = 'mailto:tu-correo@ejemplo.com';

webpush.setVapidDetails(CONTACT, VAPID_PUBLIC, VAPID_PRIVATE);

const data = $input.first().json.body || $input.first().json;
const subscription = data.subscription;
const payload = JSON.stringify(data.payload || { title: 'Descanso terminado', body: 'A la siguiente serie' });

try {
  await webpush.sendNotification(subscription, payload);
  return [{ json: { sent: true } }];
} catch (err) {
  return [{ json: { sent: false, error: String(err && err.statusCode || err) } }];
}
